  "knowledge": "High Safety-Risk Unit",
  "description": "Identifies a robot with a history of frequent or severe safety incidents.",
  "definition": "A robot is classified as a High Safety-Risk Unit if its Safety Incident Rate is greater than 2.0 OR its cumulative collision count is greater than 5."
}

