  "knowledge": "Safety Incident Rate",
  "description": "Calculates the number of safety incidents (collisions, zone, and speed violations) per 1000 hours of operation.",
  "definition": "The frequency of safety violations per 1000 operational hours. Formula: (collision_count + zone_violations + speed_violations) * 1000 / total_operational_hours."
}

{
  "id": 24,
  "knowledge": "Fault Prediction Score Tiers",
  "description": "Categorizes the raw fault prediction probability score into actionable tiers.",
  "definition": "A Fault Prediction Score is 'Low' if < 0.3 (normal operation), 'Medium' if 0.3-0.7 (monitoring required), or 'High' if > 0.7 (high probability of impending fault)."
}

{
  "id": 64,
  "knowledge": "High Safety-Risk",
  "description": "Identifies robots that pose a significant safety hazard based on their history of incidents, considering both absolute counts and incident rates.",
  "definition": "A robot is classified as 'High Safety-Risk' if it meets either of the following criteria: 1. It has experienced more than 5 total collisions. 2. Its combined rate of major incidents (collisions, zone violations, and speed violations) is greater than 2.0 per 1000 hours of operation."
}

{
  "id": 25,
  "knowledge": "Condition Index Tiers",
  "description": "Translates the composite health index score into qualitative ratings of the robot's condition.",
  "definition": "A Condition Index is 'Excellent' if > 0.9, 'Good' if 0.7-0.9, 'Fair' if 0.5-0.7, or 'Poor' if < 0.5 (significant wear or risk)."
}

{
  "id": 62,
  "knowledge": "Critical Condition Robot",
  "description": "A robot that is simultaneously at risk from both thermal and mechanical issues.",
  "definition": "A robot is in 'Critical Condition' if it has both a 'Thermal Anomaly' AND a 'Mechanical Degradation Alert'."
}

{
  "id": 43,
  "knowledge": "Thermal Anomaly",
  "description": "Identifies a potential thermal issue in a robot's joints based on temperature deviations.",
  "definition": "A Thermal Anomaly is flagged if the Average Joint Temperature exceeds 75\u00b0C or if the Joint Temperature Differential is greater than 15\u00b0C."
}

{
  "id": 47,
  "knowledge": "Mechanical Degradation Alert",
  "description": "A composite alert for significant mechanical wear based on multiple indicators.",
  "definition": "A Mechanical Degradation Alert is triggered if the robot's Average Backlash corresponds to a 'High' Backlash Severity, or its Average Joint Vibration exceeds 3.0 mm/s."
}
